import { Component, inject, signal, computed, resource } from '@angular/core';
import { Router } from '@angular/router';
import { SolicitudService } from '../../../../shared/services/solicitud.service';
import { UserService } from '../../../../services/user.service';
import { ToastService } from '../../../../shared/services/toast.service';
import { NavigationHistoryService } from '../../../../services/navigation-history.service';
import type { Solicitud } from '../../../../shared/models/solicitud.model';
import { firstValueFrom } from 'rxjs';
import { PaginatorComponent } from '../../../../shared/components/paginator/paginator.component';

@Component({
  selector: 'app-asignar-evaluador',
  imports: [PaginatorComponent],
  template: `
    <div class="container py-4">
      <div class="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h4 class="mb-1 fw-bold">Asignar Evaluador</h4>
          <p class="text-muted mb-0 small">
            Asigna las solicitudes de trámite pendientes a los funcionarios evaluadores del estado.
          </p>
        </div>
      </div>

      <div class="card mb-3 shadow-sm border-0">
        <div class="card-body">
          <div class="row g-3">
            <div class="col-md-6">
              <input
                type="text"
                class="form-control"
                placeholder="Buscar por folio o solicitante..."
                [value]="searchTerm()"
                (input)="onSearchInput($event)"
              />
            </div>
            <div class="col-md-3">
              <select
                class="form-select"
                [value]="statusFilter()"
                (change)="onStatusChange($event)"
              >
                <option value="Todos">Todos los estados</option>
                <option value="Enviada">Enviada</option>
                <option value="Incompleta">Incompleta</option>
                <option value="Subsanada">Subsanada</option>
                <option value="En Análisis">En Análisis</option>
              </select>
            </div>
            <div class="col-md-3 text-end">
              <button
                class="btn btn-outline-secondary btn-sm"
                [attr.aria-expanded]="showFilters()"
                (click)="toggleFilters()"
              >
                <i class="bi bi-funnel"></i> Filtros
              </button>
            </div>
          </div>

          @if (showFilters()) {
            <div class="row g-3 mt-1">
              <div class="col-md-3">
                <label class="form-label small mb-1" for="fechaDesde">Fecha desde</label>
                <input
                  id="fechaDesde"
                  type="date"
                  class="form-control"
                  [value]="dateFrom()"
                  (change)="onDateFromChange($event)"
                />
              </div>
              <div class="col-md-3">
                <label class="form-label small mb-1" for="fechaHasta">Fecha hasta</label>
                <input
                  id="fechaHasta"
                  type="date"
                  class="form-control"
                  [value]="dateTo()"
                  (change)="onDateToChange($event)"
                />
              </div>
              <div class="col-md-6 d-flex align-items-end">
                <button
                  class="btn btn-outline-danger btn-sm"
                  [disabled]="!dateFrom() && !dateTo()"
                  (click)="clearFilters()"
                >
                  Limpiar filtros
                </button>
              </div>
            </div>
          }
        </div>
      </div>

      @if (evaluadoresResource.error()) {
        <div class="alert alert-warning d-flex align-items-center mb-3" role="alert">
          <i class="bi bi-exclamation-triangle me-2"></i>
          <div>
            No se pudieron cargar los evaluadores. Intenta recargar la página o revisa tu conexión.
          </div>
        </div>
      }

      @if (isLoading()) {
        <div class="text-center py-5">
          <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Cargando...</span>
          </div>
        </div>
      } @else if (solicitudes().length === 0) {
        <div class="card border-0 shadow-sm">
          <div class="card-body text-center py-5 text-muted">
            No hay solicitudes de trámite pendientes de asignación.
          </div>
        </div>
      } @else {
        <div class="card border-0 shadow-sm">
          <div class="table-responsive">
            <table class="table table-hover align-middle mb-0">
              <thead class="table-light">
                <tr>
                  <th>Folio</th>
                  <th>Solicitante</th>
                  <th>Proyecto / Trámite</th>
                  <th>Fecha Recepción</th>
                  <th>Status</th>
                  <th class="text-end">Acción</th>
                </tr>
              </thead>
              <tbody>
                @for (solicitud of solicitudes(); track solicitud.id) {
                  <tr>
                    <td>
                      <a
                        href="javascript:void(0)"
                        (click)="verDetalle(solicitud.folio)"
                        class="text-decoration-none fw-bold"
                      >
                        {{ solicitud.folio }}
                      </a>
                    </td>
                    <td>{{ solicitud.solicitante }}</td>
                    <td>{{ solicitud.proyecto || '—' }}</td>
                    <td>{{ solicitud.fechaRecepcion }}</td>
                    <td>
                      <span class="badge" [class]="statusBadgeClass(solicitud.status)">
                        {{ solicitud.status }}
                      </span>
                    </td>
                    <td class="text-end">
                      <div class="d-flex gap-2 justify-content-end align-items-center">
                        <select
                          class="form-select form-select-sm"
                          style="width: 220px"
                          [value]="selectedEvaluador(solicitud.id) || ''"
                          (change)="onEvaluadorChange(solicitud.id, $event)"
                        >
                          <option value="" disabled>Seleccionar evaluador...</option>
                          @for (evaluador of evaluadores(); track evaluador.id) {
                            <option [value]="evaluador.id">{{ evaluador.name }}</option>
                          }
                        </select>
                        <button
                          class="btn btn-primary btn-sm"
                          [disabled]="!selectedEvaluador(solicitud.id) || isAssigning()"
                          (click)="asignar(solicitud)"
                        >
                          @if (isAssigning()) {
                            <span class="spinner-border spinner-border-sm" role="status"></span>
                          } @else {
                            Asignar
                          }
                        </button>
                      </div>
                    </td>
                  </tr>
                }
              </tbody>
            </table>
          </div>
        </div>

        @if (paginationMeta().lastPage > 1) {
          <div class="mt-3">
            <app-paginator
              [currentPage]="paginationMeta().currentPage"
              [lastPage]="paginationMeta().lastPage"
              [total]="paginationMeta().total"
              [perPage]="paginationMeta().perPage"
              (pageChange)="onPageChange($event)"
            />
          </div>
        }
      }
    </div>
  `,
})
export class AsignarEvaluadorComponent {
  private readonly router = inject(Router);
  private readonly solicitudService = inject(SolicitudService);
  private readonly userService = inject(UserService);
  private readonly toastService = inject(ToastService);
  private readonly navHistory = inject(NavigationHistoryService);

  readonly searchTerm = signal('');
  readonly statusFilter = signal('Todos');
  readonly showFilters = signal(false);
  readonly dateFrom = signal('');
  readonly dateTo = signal('');
  readonly page = signal(1);
  readonly perPage = signal(15);
  readonly isAssigning = signal(false);
  readonly evaluadorSelections = signal<Map<number, number>>(new Map());

  readonly evaluadoresResource = resource({
    loader: async () => {
      const result = await firstValueFrom(
        this.userService.getUsers({ role: 'ejecutivo', perPage: 100 }),
      );
      return result.users;
    },
  });

  readonly evaluadores = computed(() =>
    this.evaluadoresResource.hasValue() ? this.evaluadoresResource.value()! : [],
  );

  readonly queryParams = computed(() => ({
    tipo: 'tramite' as const,
    search: this.searchTerm().trim() || undefined,
    status: this.statusFilter() === 'Todos' ? undefined : this.statusFilter(),
    dateFrom: this.dateFrom() || undefined,
    dateTo: this.dateTo() || undefined,
    page: this.page(),
    perPage: this.perPage(),
    sinEvaluador: true,
  }));

  readonly solicitudesResource = resource({
    params: () => this.queryParams(),
    loader: async ({ params }) => {
      return firstValueFrom(this.solicitudService.getSolicitudes(params));
    },
  });

  readonly solicitudes = computed(() =>
    this.solicitudesResource.hasValue() ? this.solicitudesResource.value()!.data : [],
  );

  readonly paginationMeta = computed(() => {
    const v = this.solicitudesResource.value();
    return v
      ? { currentPage: v.current_page, lastPage: v.last_page, total: v.total, perPage: v.per_page }
      : { currentPage: 1, lastPage: 1, total: 0, perPage: 15 };
  });

  readonly isLoading = computed(() => this.solicitudesResource.isLoading());

  selectedEvaluador(solicitudId: number): number | undefined {
    return this.evaluadorSelections().get(solicitudId);
  }

  onSearchInput(event: Event): void {
    this.searchTerm.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  onStatusChange(event: Event): void {
    this.statusFilter.set((event.target as HTMLSelectElement).value);
    this.page.set(1);
  }

  toggleFilters(): void {
    this.showFilters.update((visible) => !visible);
  }

  onDateFromChange(event: Event): void {
    this.dateFrom.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  onDateToChange(event: Event): void {
    this.dateTo.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  clearFilters(): void {
    this.dateFrom.set('');
    this.dateTo.set('');
    this.page.set(1);
  }

  onPageChange(page: number): void {
    this.page.set(page);
  }

  onEvaluadorChange(solicitudId: number, event: Event): void {
    const evaluadorId = Number((event.target as HTMLSelectElement).value);
    if (!evaluadorId) return;

    this.evaluadorSelections.update((map) => {
      const next = new Map(map);
      next.set(solicitudId, evaluadorId);
      return next;
    });
  }

  async asignar(solicitud: Solicitud): Promise<void> {
    const evaluadorId = this.selectedEvaluador(solicitud.id);
    if (!evaluadorId) return;

    this.isAssigning.set(true);
    try {
      await firstValueFrom(
        this.solicitudService.asignarEvaluador(solicitud.folio, evaluadorId),
      );
      this.toastService.success(
        `Solicitud ${solicitud.folio} asignada con éxito.`,
      );
      this.evaluadorSelections.update((map) => {
        const next = new Map(map);
        next.delete(solicitud.id);
        return next;
      });
      this.solicitudesResource.reload();
    } catch {
      this.toastService.error('Ocurrió un error al asignar el evaluador.');
    } finally {
      this.isAssigning.set(false);
    }
  }

  verDetalle(folio: string): void {
    this.navHistory.recordBackPath('tramites/asignar-evaluador');
    this.router.navigate(['/ejecutivos/solicitudes', folio], {
      queryParams: { from: 'tramites/asignar-evaluador' },
    });
  }

  statusBadgeClass(status: string): string {
    switch (status) {
      case 'Enviada':
        return 'bg-info text-dark';
      case 'En Análisis':
        return 'bg-primary-subtle text-primary border border-primary';
      case 'Incompleta':
        return 'bg-secondary';
      case 'Subsanada':
        return 'bg-warning text-dark';
      case 'En Firma':
        return 'bg-warning-subtle text-warning border border-warning';
      case 'Terminada':
      case 'Aprobada':
        return 'bg-success';
      case 'No Autorizada':
      case 'No Aprobada':
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }
}
